    },
    {
      "var_name": "VAR_demand_surplus_slack",
      "var_type": "continuous",
      "index_sets": [
        "DEMAND_IDS"
      ],
      "lower_bound": 0,
      "desc": "【场景1-上限松弛】需求硬边界上限过剩松弛变量，代表突破需求边界的规模，非负"
    },
    {
      "var_name": "VAR_demand_min_cover_slack",
      "var_type": "continuous",
      "index_sets": [
        "DEMAND_IDS"
      ],
      "lower_bound": 0,
      "desc": "【场景2-最小量兜底】需求最小量达标缺口松弛变量，代表未达最小量的缺口，非负"
