            path_flows.append({
                "resource_id": path_seq[0],   # 第一个元素
                "demand_id": path_seq[-1],    # 最后一个元素
                "flow": round(flow_value, 2),
                "path_nodes": path_nodes,
                "path_edges": path_edges
            })

    # 计算总成本
    total_cost = model.objective()

    return {
        "status": "success",
        "objective_value": round(total_cost, 2),
        "path_flows": path_flows,
        "num_active_paths": len(path_flows),
        "solver_time": results.solver.time,
        "excel_output": excel_path
    }
```

